{
  "permissions": {
    "deny": [
      "Read(./**/dist/**/*)",
      "Read(./**/build/**/*)",
      "Read(./**/*.generated.*)",
      "Read(./**/vendor/**/*)"
    ]
  },
  "worktree": {
    "sparsePaths": [".claude", "packages/api", "packages/shared"]
  }
}

{
  "permissions": {
    "defaultMode": "default"
  }
}

{
  "permissions": {
    "allow": [
      "Bash(npm run lint)",
      "Bash(npm run test *)"
